<script setup lang="ts">
import {normalizePaymentPin,editPaymentPin} from './payment-pin'
import {type Locale} from './i18n'
import UiIcon from './UiIcon.vue'
const props=defineProps<{modelValue:string;label:string;locale:Locale;disabled:boolean;error?:string}>()
const emit=defineEmits<{'update:modelValue':[value:string]}>()
const words={'zh-CN':['清空','删除一位'],en:['Clear','Delete digit'],ja:['クリア','一桁削除'],ko:['지우기','한 자리 삭제'],fr:['Effacer','Supprimer un chiffre'],de:['Leeren','Ziffer löschen'],'zh-TW':['清空','刪除一位']}
function key(value:string){if(!props.disabled)emit('update:modelValue',editPaymentPin(props.modelValue,value))}
function input(event:Event){const node=event.target as HTMLInputElement;const value=props.disabled?props.modelValue:normalizePaymentPin(node.value);node.value=value;if(!props.disabled)emit('update:modelValue',value)}
</script>
<template><div aria-hidden="false" class="flex justify-center items-center gap-2 mb-3 source-pin-container" id="pin-dots-container"><div :class="modelValue.length>=n?['border-emerald-500','bg-emerald-50/30']:['border-slate-200','bg-slate-50']" :key="n" aria-hidden="true" class="pin-box w-10 h-12 rounded-xl border-2 flex items-center justify-center text-lg font-bold text-slate-900 transition-all" v-for="n in 6">{{modelValue.length>=n?'●':''}}</div><input :aria-label="label" :readonly="disabled" :value="modelValue" @input="input" autocomplete="off" class="source-pin-input" inputmode="none" maxlength="6" type="password"/></div><div class="h-6 flex items-center justify-center text-xs font-medium text-red-600 transition-opacity mb-2" id="pwd-error-tip" role="alert" :class="{'opacity-0':!error}" :aria-hidden="!error">{{error}}</div><div class="grid grid-cols-3 gap-2 w-full pt-1"><button :disabled="disabled" @click="key('1')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="1" type="button">1</button><button :disabled="disabled" @click="key('2')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="2" type="button">2</button><button :disabled="disabled" @click="key('3')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="3" type="button">3</button><button :disabled="disabled" @click="key('4')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="4" type="button">4</button><button :disabled="disabled" @click="key('5')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="5" type="button">5</button><button :disabled="disabled" @click="key('6')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="6" type="button">6</button><button :disabled="disabled" @click="key('7')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="7" type="button">7</button><button :disabled="disabled" @click="key('8')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="8" type="button">8</button><button :disabled="disabled" @click="key('9')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="9" type="button">9</button><button :disabled="disabled" @click="key('clear')" class="keypad-btn py-2.5 bg-slate-50 hover:bg-slate-100 rounded-xl text-xs font-medium text-slate-500 transition-colors flex items-center justify-center" data-key="clear" type="button">{{words[locale][0]}}</button><button :disabled="disabled" @click="key('0')" class="keypad-btn py-2.5 bg-slate-100/80 hover:bg-slate-200/80 active:bg-slate-300/80 rounded-xl text-lg font-semibold text-slate-800 transition-colors" data-key="0" type="button">0</button><button :aria-label="words[locale][1]" :disabled="disabled" @click="key('backspace')" class="keypad-btn py-2.5 bg-slate-50 hover:bg-slate-100 rounded-xl text-slate-600 transition-colors flex items-center justify-center" data-key="backspace" type="button"><UiIcon :size="20" class="material-symbols-outlined text-[20px]" name="backspace"></UiIcon></button></div></template>
